def test_update_email_invalid_email_raises():
    with pytest.raises(ValueError, match="invalid email"):
        update_email(1, "not-an-email")

def test_update_email_success_returns_true(monkeypatch):
    dummy_user = {"email": "old@example.com"}
    monkeypatch.setattr('app.services.user.get_user', lambda uid: dummy_user)
    result = update_email(1, "new@example.com")
    assert result is True
    assert dummy_user["email"] == "new@example.com"
